import { useEffect, useRef, useState } from 'react';
import {
  auraCategories,
  auraPieces,
  type AuraCategory,
  type AuraPiece,
} from '@/data/demos/aura-clothing';

/**
 * AURA Clothing demo: lookbook shop that ends in an enquiry. Fictional brand.
 * Palette: black #111111, ivory #F7F3EE, champagne #CDB89A, stone #8A8175.
 *
 * Product photos load from src/assets/demos/aura-clothing/<piece id>.(webp|jpg|png) when
 * they exist (generated by the owner's Grok bot, see docs/IMAGE-REQUESTS.md). Until then
 * each piece shows a tonal placeholder, so nothing looks broken.
 */
const photos = import.meta.glob<{ src: string }>(
  '/src/assets/demos/aura-clothing/*.{webp,jpg,jpeg,png}',
  { eager: true, import: 'default' },
);
const photoFor = (id: string) =>
  Object.entries(photos).find(([path]) => path.split('/').pop()?.startsWith(`${id}.`))?.[1]?.src;

interface BagItem {
  id: string;
  size: string;
}

const focusRing =
  'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#CDB89A]';

export default function AuraClothingDemo() {
  const [filter, setFilter] = useState<AuraCategory | 'all'>('all');
  const [openId, setOpenId] = useState<string | null>(null);
  const [bagOpen, setBagOpen] = useState(false);
  const [bag, setBag] = useState<BagItem[]>([]);
  const [notice, setNotice] = useState('');
  const root = useRef<HTMLDivElement>(null);
  const viewHeading = useRef<HTMLHeadingElement>(null);
  const returnTo = useRef<string | null>(null);

  const open = openId ? auraPieces.find((piece) => piece.id === openId) : undefined;
  const shown = filter === 'all' ? auraPieces : auraPieces.filter((p) => p.category === filter);

  // Move focus to the heading of each new view so keyboard and screen-reader users follow along.
  useEffect(() => {
    if (openId || bagOpen) {
      // Start each new view at the top of the shop, below the sticky demo bar.
      root.current?.scrollIntoView({ block: 'start' });
      viewHeading.current?.focus({ preventScroll: true });
    } else if (returnTo.current) {
      document.getElementById(`aura-card-${returnTo.current}`)?.focus();
      returnTo.current = null;
    }
  }, [openId, bagOpen]);

  const showPiece = (id: string) => {
    returnTo.current = id;
    setNotice('');
    setOpenId(id);
  };

  const addToBag = (piece: AuraPiece, size: string) => {
    setBag((items) =>
      items.some((item) => item.id === piece.id && item.size === size)
        ? items
        : [...items, { id: piece.id, size }],
    );
    setNotice(`${piece.name} (${size}) added to your enquiry bag.`);
  };

  return (
    <div ref={root} className="scroll-mt-40 bg-[#F7F3EE] font-sans text-[#111111]">
      <header className="flex items-center justify-between gap-3 bg-[#111111] px-4 py-3 text-[#F7F3EE] sm:px-6">
        <button
          type="button"
          onClick={() => {
            setOpenId(null);
            setBagOpen(false);
          }}
          className={`font-display text-lg font-semibold tracking-[0.4em] ${focusRing}`}
          aria-label="AURA, back to the collection"
        >
          AURA
        </button>
        <button
          type="button"
          onClick={() => {
            setOpenId(null);
            setBagOpen(true);
            setNotice('');
          }}
          className={`min-h-11 rounded-full border border-[#CDB89A]/60 px-4 text-sm font-semibold ${focusRing}`}
          data-aura-bag-button
        >
          Enquiry bag <span aria-hidden="true">({bag.length})</span>
          <span className="sr-only">
            , {bag.length} {bag.length === 1 ? 'piece' : 'pieces'}
          </span>
        </button>
      </header>

      {bagOpen ? (
        <Bag
          headingRef={viewHeading}
          bag={bag}
          onRemove={(index) => setBag((items) => items.filter((_, i) => i !== index))}
          onBack={() => setBagOpen(false)}
          onSend={() =>
            setNotice(
              'Demo: on a real shop this opens WhatsApp with your list of pieces and sizes, so the label can confirm fit and availability.',
            )
          }
          notice={notice}
        />
      ) : open ? (
        <PieceView
          headingRef={viewHeading}
          piece={open}
          inBag={bag.filter((item) => item.id === open.id).map((item) => item.size)}
          onAdd={(size) => addToBag(open, size)}
          onBack={() => setOpenId(null)}
          notice={notice}
        />
      ) : (
        <div className="mx-auto max-w-4xl px-4 py-6 sm:px-6 sm:py-8">
          <p className="text-xs font-semibold tracking-[0.2em] text-[#5c554d] uppercase">
            The collection
          </p>
          <h2 className="font-display mt-1 text-2xl font-semibold sm:text-3xl">
            Tailoring, ready to wear and accessories.
          </h2>

          <div
            role="group"
            aria-label="Filter the collection"
            className="mt-5 flex flex-wrap gap-2"
            data-aura-filters
          >
            {[{ id: 'all' as const, label: 'All' }, ...auraCategories].map((option) => {
              const count =
                option.id === 'all'
                  ? auraPieces.length
                  : auraPieces.filter((p) => p.category === option.id).length;
              const active = filter === option.id;
              return (
                <button
                  key={option.id}
                  type="button"
                  aria-pressed={active}
                  onClick={() => setFilter(option.id)}
                  className={`min-h-11 rounded-full border px-4 text-sm font-semibold transition ${focusRing} ${
                    active
                      ? 'border-[#111111] bg-[#111111] text-[#F7F3EE]'
                      : 'border-[#111111]/25 hover:border-[#111111]'
                  }`}
                >
                  {option.label} <span className="opacity-70">{count}</span>
                </button>
              );
            })}
          </div>

          <ul
            className="mx-auto mt-6 grid max-w-4xl grid-cols-2 gap-3 sm:grid-cols-3 sm:gap-5"
            data-aura-grid
          >
            {shown.map((piece) => (
              <li key={piece.id}>
                <button
                  id={`aura-card-${piece.id}`}
                  type="button"
                  onClick={() => showPiece(piece.id)}
                  className={`group block w-full text-left ${focusRing}`}
                >
                  <Photo piece={piece} className="aspect-[4/5]" />
                  <span className="mt-2 block text-sm font-semibold">{piece.name}</span>
                  <span className="block text-xs text-[#5c554d]">
                    {auraCategories.find((c) => c.id === piece.category)?.label}
                  </span>
                </button>
              </li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
}

function Photo({ piece, className = '' }: { piece: AuraPiece; className?: string }) {
  const src = photoFor(piece.id);
  return (
    <span
      className={`relative block overflow-hidden rounded-lg ${className}`}
      style={{ background: `linear-gradient(160deg, ${piece.tone[0]}, ${piece.tone[1]})` }}
    >
      {src ? (
        <img
          src={src}
          alt=""
          loading="lazy"
          className="h-full w-full object-cover transition duration-500 group-hover:scale-[1.03]"
        />
      ) : (
        <span
          aria-hidden="true"
          className="font-display absolute inset-0 flex items-end p-3 text-xs tracking-[0.3em] text-white/70 mix-blend-difference"
        >
          AURA
        </span>
      )}
    </span>
  );
}

function PieceView({
  piece,
  inBag,
  onAdd,
  onBack,
  notice,
  headingRef,
}: {
  piece: AuraPiece;
  inBag: string[];
  onAdd: (size: string) => void;
  onBack: () => void;
  notice: string;
  headingRef: React.RefObject<HTMLHeadingElement | null>;
}) {
  const oneSize = piece.sizes.length === 1;
  const [size, setSize] = useState(oneSize ? piece.sizes[0] : '');
  const [prompted, setPrompted] = useState(false);

  return (
    <div className="mx-auto grid max-w-4xl gap-6 px-4 py-6 sm:grid-cols-[minmax(0,1fr)_minmax(0,1fr)] sm:px-6 sm:py-8">
      <Photo piece={piece} className="aspect-[3/4] sm:aspect-[4/5]" />
      <div>
        <button
          type="button"
          onClick={onBack}
          className={`min-h-11 text-sm font-semibold underline underline-offset-4 ${focusRing}`}
        >
          Back to the collection
        </button>
        <h2
          ref={headingRef}
          tabIndex={-1}
          className="font-display mt-3 text-2xl font-semibold outline-none sm:text-3xl"
        >
          {piece.name}
        </h2>
        <p className="mt-2 text-[#3d3832]">{piece.description}</p>
        <p className="mt-3 text-sm text-[#5c554d]">Fabric: {piece.fabric}</p>

        <fieldset className="mt-6">
          <legend className="text-sm font-semibold">Size</legend>
          <div className="mt-2 flex flex-wrap gap-2" data-aura-sizes>
            {piece.sizes.map((option) => (
              <button
                key={option}
                type="button"
                aria-pressed={size === option}
                onClick={() => {
                  setSize(option);
                  setPrompted(false);
                }}
                className={`min-h-11 min-w-11 rounded-md border px-3 text-sm font-semibold ${focusRing} ${
                  size === option
                    ? 'border-[#111111] bg-[#111111] text-[#F7F3EE]'
                    : 'border-[#111111]/25 hover:border-[#111111]'
                }`}
              >
                {option}
              </button>
            ))}
          </div>
        </fieldset>

        <button
          type="button"
          onClick={() => {
            if (!size) {
              setPrompted(true);
              return;
            }
            onAdd(size);
          }}
          aria-describedby={prompted ? 'aura-size-hint' : undefined}
          className={`mt-6 min-h-12 w-full rounded-full bg-[#111111] px-6 text-sm font-semibold text-[#F7F3EE] hover:bg-[#2b2724] sm:w-auto ${focusRing}`}
        >
          Add to enquiry bag
        </button>
        <p
          id="aura-size-hint"
          role="status"
          className={`mt-3 min-h-5 text-sm ${prompted ? 'font-semibold text-[#8a2e1d]' : 'text-[#3d3832]'}`}
        >
          {prompted
            ? 'Choose a size first.'
            : inBag.length > 0
              ? `In your bag: ${inBag.join(', ')}.`
              : notice}
        </p>
        <p className="mt-4 text-xs text-[#5c554d]">
          No prices or stock here: AURA is an invented brand. A real label would confirm fit, price
          and availability when you enquire.
        </p>
      </div>
    </div>
  );
}

function Bag({
  bag,
  onRemove,
  onBack,
  onSend,
  notice,
  headingRef,
}: {
  bag: BagItem[];
  onRemove: (index: number) => void;
  onBack: () => void;
  onSend: () => void;
  notice: string;
  headingRef: React.RefObject<HTMLHeadingElement | null>;
}) {
  return (
    <div className="px-4 py-6 sm:px-6 sm:py-8" data-aura-bag>
      <button
        type="button"
        onClick={onBack}
        className={`min-h-11 text-sm font-semibold underline underline-offset-4 ${focusRing}`}
      >
        Back to the collection
      </button>
      <h2
        ref={headingRef}
        tabIndex={-1}
        className="font-display mt-3 text-2xl font-semibold outline-none sm:text-3xl"
      >
        Your enquiry bag
      </h2>
      {bag.length === 0 ? (
        <p className="mt-3 text-[#3d3832]">
          Nothing here yet. Open a piece, choose a size and add it.
        </p>
      ) : (
        <>
          <ul className="mt-5 divide-y divide-[#111111]/10 border-y border-[#111111]/10">
            {bag.map((item, index) => {
              const piece = auraPieces.find((p) => p.id === item.id)!;
              return (
                <li key={`${item.id}-${item.size}`} className="flex items-center gap-4 py-3">
                  <Photo piece={piece} className="aspect-[3/4] w-14 shrink-0" />
                  <div className="min-w-0 flex-1">
                    <p className="font-semibold">{piece.name}</p>
                    <p className="text-sm text-[#5c554d]">Size: {item.size}</p>
                  </div>
                  <button
                    type="button"
                    onClick={() => onRemove(index)}
                    className={`min-h-11 px-2 text-sm font-semibold underline underline-offset-4 ${focusRing}`}
                  >
                    Remove<span className="sr-only"> {piece.name}</span>
                  </button>
                </li>
              );
            })}
          </ul>
          <button
            type="button"
            onClick={onSend}
            className={`mt-6 min-h-12 w-full rounded-full bg-[#111111] px-6 text-sm font-semibold text-[#F7F3EE] sm:w-auto ${focusRing}`}
          >
            Send enquiry
          </button>
        </>
      )}
      <p role="status" className="mt-4 min-h-5 text-sm font-semibold text-[#3d3832]">
        {notice.startsWith('Demo:') ? notice : ''}
      </p>
    </div>
  );
}
